function eloExpect(ra, rb){
  if(typeof ra!=='number'||typeof rb!=='number'||!isFinite(ra)||!isFinite(rb))
    return { value:null, error:'等级分必须是有限数' };
  return { value: 1/(1+Math.pow(10,(rb-ra)/400)), error:null };
}
function eloUpdate(ra, rb, scoreA, k){
  var e=eloExpect(ra,rb);
  if(e.error) return { value:null, error:e.error };
  if(scoreA!==0&&scoreA!==1&&scoreA!==0.5) return { value:null, error:'比分必须是 0 / 0.5 / 1' };
  var kk=(typeof k==='number'&&k>0)?k:32;
  var ea=e.value;
  var na=ra+kk*(scoreA-ea);
  var nb=rb+kk*((1-scoreA)-(1-ea));
  return { value:{ ra:Math.round(na*100)/100, rb:Math.round(nb*100)/100,
    expectA:Math.round(ea*10000)/10000, deltaA:Math.round(kk*(scoreA-ea)*100)/100 }, error:null };
}
function eloSeries(ra, rb, scores, k){
  if(!Array.isArray(scores)||!scores.length) return { value:null, error:'对局序列为空' };
  var hist=[], a=ra, b=rb;
  for(var i=0;i<scores.length;i++){
    var r=eloUpdate(a,b,scores[i],k);
    if(r.error) return { value:null, error:'第 '+(i+1)+' 局: '+r.error };
    hist.push({ game:i+1, score:scores[i], expectA:r.value.expectA, deltaA:r.value.deltaA,
      ra:r.value.ra, rb:r.value.rb });
    a=r.value.ra; b=r.value.rb;
  }
  return { value:{ history:hist, finalA:a, finalB:b }, error:null };
}
if (typeof module !== 'undefined' && module.exports) {
  module.exports = { eloExpect:eloExpect, eloUpdate:eloUpdate, eloSeries:eloSeries };
}
if (typeof window !== 'undefined') {
  window.EloForgePure = { eloExpect:eloExpect, eloUpdate:eloUpdate, eloSeries:eloSeries };
}
